    private var closedFlag = false
    private var recvBuffer: [UInt8] = []

    /// Cleartext (h2c, prior knowledge) connection to authority.
    static func Dial(_ authority: String) throws -> Http2Transport {
        return try Http2Transport(authority, tls: false)
    }

    /// TLS is not offered by the generated Swift transport (no
    /// stdlib TLS on this platform): throws CodeUnimplemented.
    static func DialTls(_ authority: String) throws -> Http2Transport {
        throw StatusException(Wire.CodeUnimplemented,
                              "generated Swift HTTP/2 transport has no TLS (no stdlib TLS on this platform)")
    }

    private init(_ authority: String, tls: Bool) throws {
        self.authority = authority
        self.scheme = tls ? "https" : "http"
        var host = authority
        var port = tls ? 443 : 80
        if let colon = authority.lastIndex(of: ":") {
            host = String(authority[authority.startIndex..<colon])
            port = Int(authority[authority.index(after: colon)...]) ?? port
        }
        self.fd = try Http2Transport.connect(host, port)
        // Connection preface + an empty SETTINGS frame.
        WriteRaw([UInt8]("PRI * HTTP/2.0\r\n\r\nSM\r\n\r\n".utf8))
        WriteFrame(Http2Transport.H2Settings, 0, 0, [])
        DispatchQueue.global(qos: .utility).async { [self] in
            ReaderLoop()
        }
    }

    private static func connect(_ host: String, _ port: Int) throws -> Int32 {
        let fd = Glibc.socket(AF_INET, Int32(SOCK_STREAM.rawValue), 0)
        if fd < 0 {
            throw StatusException(Wire.CodeUnavailable, "socket() failed")
        }
        var addr = sockaddr_in()
        addr.sin_family = sa_family_t(AF_INET)
        addr.sin_port = UInt16(port).bigEndian
        var ip = in_addr()
        if host == "localhost" {
            addr.sin_addr.s_addr = Glibc.htonl(0x7f000001)
        } else if Glibc.inet_pton(AF_INET, host, &ip) == 1 {
            addr.sin_addr = ip
        } else {
            Glibc.close(fd)
            throw StatusException(Wire.CodeUnavailable, "cannot resolve host \(host)")
        }
        let result = withUnsafePointer(to: &addr) { ptr in
            ptr.withMemoryRebound(to: sockaddr.self, capacity: 1) { sa in
                Glibc.connect(fd, sa, socklen_t(MemoryLayout<sockaddr_in>.size))
            }
        }
        if result != 0 {
            Glibc.close(fd)
            throw StatusException(Wire.CodeUnavailable, "connect to \(host):\(port) failed")
        }
        return fd
    }

    private func WriteRaw(_ bytes: [UInt8]) {
        sendLock.lock()
        defer { sendLock.unlock() }
        var off = 0
        while off < bytes.count {
            let n = bytes.withUnsafeBytes { raw -> Int in
                guard let base = raw.baseAddress else { return -1 }
                return Glibc.send(fd, base + off, bytes.count - off, Int32(MSG_NOSIGNAL))
            }
            if n <= 0 {
                return
            }
            off += n
        }
    }

    private func WriteFrame(_ type: Int, _ flags: Int, _ streamId: UInt32, _ payload: [UInt8]) {
        var header = [UInt8](repeating: 0, count: 9)
        header[0] = UInt8((payload.count >> 16) & 0xff)
        header[1] = UInt8((payload.count >> 8) & 0xff)
        header[2] = UInt8(payload.count & 0xff)
        header[3] = UInt8(type & 0xff)
        header[4] = UInt8(flags & 0xff)
        header[5] = UInt8((streamId >> 24) & 0x7f)
        header[6] = UInt8((streamId >> 16) & 0xff)
        header[7] = UInt8((streamId >> 8) & 0xff)
        header[8] = UInt8(streamId & 0xff)
        WriteRaw(header + payload)
    }

    private func Emit(_ frameType: Int, _ streamId: UInt32, _ payload: [UInt8]) {
        if let frame = try? Codec.EncodeFrame(frameType, streamId, payload) {
            queue.Add(frame)
        }
    }

    private func EmitHeadersFrame(_ streamId: UInt32, _ metadata: [String: String]) {
        let entries = metadata.keys.sorted().map {
            Codec.JsonEscape($0) + ":" + Codec.JsonEscape(metadata[$0] ?? "")
        }.joined(separator: ",")
        Emit(Wire.FrameHeaders, streamId, [UInt8]("{\"metadata\":{\(entries)}}".utf8))
    }

    private func EmitTrailersFrame(_ streamId: UInt32, _ code: Int, _ message: String, _ metadata: [String: String]?) {
        var status = StatusException(code, message)
        if let metadata = metadata {
            status.trailers = metadata
        }
        if let frame = try? Codec.StatusFrame(Wire.FrameTrailers, streamId, status) {
            Emit(Wire.FrameTrailers, streamId, Array(frame[Codec.HeaderLen...]))
        }
    }

    private func ReaderLoop() {
        var chunk = [UInt8](repeating: 0, count: 65536)
        while true {
            let n = chunk.withUnsafeMutableBytes { raw -> Int in
                guard let base = raw.baseAddress else { return -1 }
                return Glibc.recv(fd, base, 65536, 0)
            }
            if n <= 0 {
                break
            }
            recvBuffer.append(contentsOf: chunk[0..<n])
            while recvBuffer.count >= 9 {
                let len = (Int(recvBuffer[0]) << 16) | (Int(recvBuffer[1]) << 8) | Int(recvBuffer[2])
                if recvBuffer.count < 9 + len {
                    break
                }
                let type = Int(recvBuffer[3])
                let flags = Int(recvBuffer[4])
                let streamId = (UInt32(recvBuffer[5] & 0x7f) << 24) | (UInt32(recvBuffer[6]) << 16)
                    | (UInt32(recvBuffer[7]) << 8) | UInt32(recvBuffer[8])
                let payload = Array(recvBuffer[9..<(9 + len)])
                recvBuffer.removeFirst(9 + len)
                if !OnFrame(type, flags, streamId, payload) {
                    MarkClosed()
                    queue.Close()
                    return
                }
            }
        }
        MarkClosed()
        queue.Close()
    }

    private func MarkClosed() {
        cond.lock()
        closedFlag = true
        cond.broadcast()
        cond.unlock()
    }

    private func OnFrame(_ type: Int, _ flags: Int, _ streamId: UInt32, _ payload: [UInt8]) -> Bool {
        switch type {
        case Http2Transport.H2Settings:
            if (flags & Http2Transport.FlagAck) != 0 {
                return true
            }
            var newInitial = peerInitialWindow
            var off = 0
            while off + 6 <= payload.count {
                let ident = (Int(payload[off]) << 8) | Int(payload[off + 1])
                let value = (Int(payload[off + 2]) << 24) | (Int(payload[off + 3]) << 16)
                    | (Int(payload[off + 4]) << 8) | Int(payload[off + 5])
                if ident == 0x3 {
                    newInitial = value
                }
                off += 6
            }
            let delta = newInitial - peerInitialWindow
            peerInitialWindow = newInitial
            if delta != 0 {
                cond.lock()
                for key in Array(streamWindows.keys) {
                    streamWindows[key] = (streamWindows[key] ?? 0) + delta
                }
                cond.broadcast()
                cond.unlock()
            }
            WriteFrame(Http2Transport.H2Settings, Http2Transport.FlagAck, 0, [])
        case Http2Transport.H2WindowUpdate:
            if payload.count >= 4 {
                let inc = (Int(payload[0] & 0x7f) << 24) | (Int(payload[1]) << 16)
                    | (Int(payload[2]) << 8) | Int(payload[3])
                cond.lock()
                if streamId == 0 {
                    connWindow += inc
                } else {
                    streamWindows[streamId] = (streamWindows[streamId] ?? peerInitialWindow) + inc
                }
                cond.broadcast()
                cond.unlock()
            }
        case Http2Transport.H2Ping:
            if (flags & Http2Transport.FlagAck) == 0 && payload.count == 8 {
                WriteFrame(Http2Transport.H2Ping, Http2Transport.FlagAck, 0, payload)
            }
        case Http2Transport.H2RstStream:
            Emit(Wire.FrameRst, streamId, [UInt8]("{\"code\":8,\"message\":\"rst stream\"}".utf8))
        case Http2Transport.H2Headers, Http2Transport.H2Continuation:
            var block = headerBlocks[streamId] ?? []
            block.append(contentsOf: payload)
            headerBlocks[streamId] = block
            if (flags & Http2Transport.FlagEndHeaders) != 0 {
                headerBlocks.removeValue(forKey: streamId)
                OnHeaders(streamId, (flags & Http2Transport.FlagEndStream) != 0, block)
            }
        case Http2Transport.H2Data:
            var body = payload
            if (flags & Http2Transport.FlagPadded) != 0 && !body.isEmpty {
                let pad = Int(body[0])
                body = pad + 1 <= body.count ? Array(body[1..<(body.count - pad)]) : []
            }
            if !body.isEmpty {
                WriteFrame(Http2Transport.H2WindowUpdate, 0, 0, WindowUpdate(body.count))
                WriteFrame(Http2Transport.H2WindowUpdate, 0, streamId, WindowUpdate(body.count))
                var buf = dataBuffers[streamId] ?? []
                buf.append(contentsOf: body)
                dataBuffers[streamId] = buf
                DrainMessages(streamId)
            }
            if (flags & Http2Transport.FlagEndStream) != 0 {
                EmitTrailersFrame(streamId, 2, "missing grpc-status", nil)
            }
        default:
            // GOAWAY and unknown frames: nothing to do.
            break
        }
        return true
    }

    private func WindowUpdate(_ increment: Int) -> [UInt8] {
        return [UInt8((increment >> 24) & 0x7f), UInt8((increment >> 16) & 0xff),
                UInt8((increment >> 8) & 0xff), UInt8(increment & 0xff)]
    }

    private func OnHeaders(_ streamId: UInt32, _ endStream: Bool, _ block: [UInt8]) {
        guard let headers = try? decoder.Decode(block) else {
            return
        }
        var metadata: [String: String] = [:]
        var status: String? = nil
        var message: String? = nil
        for (name, value) in headers {
            if name == "grpc-status" {
                status = value
            } else if name == "grpc-message" {
                message = value
            } else if name == "grpc-encoding" {
                if value == "gzip" {
                    decompressIn.insert(streamId)
                }
            } else if name.hasPrefix(":") || name == "content-type" || name == "grpc-accept-encoding" {
                // transport-owned: not metadata
            } else if metadata[name] == nil {
                metadata[name] = value
            }
        }
        let first = !headersSeen.contains(streamId)
        headersSeen.insert(streamId)
        if endStream && status != nil {
            EmitTrailersFrame(streamId, Int(status!) ?? 2,
                              Http2Transport.PercentDecode(message ?? ""), metadata)
        } else if first {
            EmitHeadersFrame(streamId, metadata)
            if endStream {
                EmitTrailersFrame(streamId, 2, "missing grpc-status", metadata)
            }
        } else if endStream {
            EmitTrailersFrame(streamId, 2, "missing grpc-status", metadata)
        }
    }

    private func DrainMessages(_ streamId: UInt32) {
        guard var data = dataBuffers[streamId] else {
            return
        }
        var off = 0
        while data.count - off >= 5 {
            let mlen = (Int(data[off + 1]) << 24) | (Int(data[off + 2]) << 16)
                | (Int(data[off + 3]) << 8) | Int(data[off + 4])
            if data.count - off - 5 < mlen {
                break
            }
            let compressed = Int(data[off]) & 0xff
            var message = Array(data[(off + 5)..<(off + 5 + mlen)])
            off += 5 + mlen
            if compressed == 1 || decompressIn.contains(streamId) {
                guard let plain = try? Http2Transport.Gunzip(message) else {
                    dataBuffers[streamId] = Array(data[off...])
                    return
                }
                message = plain
            }
            Emit(Wire.FrameData, streamId, message)
        }
        data.removeFirst(off)
        dataBuffers[streamId] = data
    }

    static func PercentDecode(_ value: String) -> String {
        var bytes: [UInt8] = []
        let units = [UInt8](value.utf8)
        var i = 0
        while i < units.count {
            let c = units[i]
            if c == 0x25 && i + 2 < units.count {
                let hi = HexDigit(units[i + 1])
                let lo = HexDigit(units[i + 2])
                if hi >= 0 && lo >= 0 {
                    bytes.append(UInt8((hi << 4) | lo))
                    i += 3
                    continue
                }
            }
            bytes.append(c)
            i += 1
        }
        return String(decoding: bytes, as: UTF8.self)
    }

    private static func HexDigit(_ c: UInt8) -> Int {
        switch c {
        case 48...57: return Int(c) - 48
        case 97...102: return Int(c) - 97 + 10
        case 65...70: return Int(c) - 65 + 10
        default: return -1
        }
    }

    func Send(_ message: [UInt8]) throws {
        if message.count < 9 {
            throw StatusException(Wire.CodeInvalidArgument, "short frame")
        }
        let frame = try Codec.DecodeFrame(message)
        let streamId = frame.streamId
        let payload = frame.payload
        switch frame.type {
        case Wire.FrameHeaders:
            let headers = try Codec.ParseHeaders(payload)
            let metadata = headers.metadata
            cond.lock()
            if streamWindows[streamId] == nil {
                streamWindows[streamId] = peerInitialWindow
            }
            cond.unlock()
            if metadata["grpc-encoding"] == "gzip" {
                compressOut.insert(streamId)
            }
            var block: [UInt8] = []
            block.append(0x83) // :method: POST
            block.append(scheme == "https" ? 0x87 : 0x86) // :scheme
            Http2Transport.WriteLiteralIndexedName(&block, 4, headers.path ?? "") // :path
            Http2Transport.WriteLiteralIndexedName(&block, 1, authority) // :authority
            Http2Transport.WriteLiteralIndexedName(&block, 31, "application/grpc")
            Http2Transport.WriteLiteralNewName(&block, "grpc-accept-encoding", "gzip,identity")
            Http2Transport.WriteLiteralNewName(&block, "te", "trailers")
            for (key, value) in metadata {
                let k = key.lowercased()
                if k == "grpc-encoding" {
                    Http2Transport.WriteLiteralNewName(&block, k, "gzip")
                } else {
                    Http2Transport.WriteLiteralNewName(&block, k, value)
                }
            }
            WriteFrame(Http2Transport.H2Headers, Http2Transport.FlagEndHeaders, streamId, block)
        case Wire.FrameData:
            let compressed = compressOut.contains(streamId)
            let body = compressed ? Http2Transport.Gzip(payload) : payload
            var wire = [UInt8](repeating: 0, count: 5 + body.count)
            wire[0] = compressed ? 1 : 0
            wire[1] = UInt8((body.count >> 24) & 0xff)
            wire[2] = UInt8((body.count >> 16) & 0xff)
            wire[3] = UInt8((body.count >> 8) & 0xff)
            wire[4] = UInt8(body.count & 0xff)
            wire.replaceSubrange(5..<wire.count, with: body)
            var sent = 0
            while sent < wire.count {
                var allowance = 0
                cond.lock()
                while !closedFlag && (connWindow <= 0 || (streamWindows[streamId] ?? peerInitialWindow) <= 0) {
                    cond.wait()
                }
                if closedFlag {
                    cond.unlock()
                    throw StatusException(Wire.CodeUnavailable, "transport closed")
                }
                let sw = streamWindows[streamId] ?? peerInitialWindow
                allowance = min(min(connWindow, sw),
                                min(Http2Transport.MaxFramePayload, wire.count - sent))
                connWindow -= allowance
                streamWindows[streamId] = sw - allowance
                cond.unlock()
                WriteFrame(Http2Transport.H2Data, 0, streamId,
                           Array(wire[sent..<(sent + allowance)]))
                sent += allowance
            }
        case Wire.FrameHalfClose:
            WriteFrame(Http2Transport.H2Data, Http2Transport.FlagEndStream, streamId, [])
        case Wire.FrameRst:
            WriteFrame(Http2Transport.H2RstStream, 0, streamId, [0, 0, 0, 8])
        default:
            // Trailers never travel client -> server here.
            break
        }
    }

    func Recv() throws -> [UInt8] {
        guard let msg = queue.Take() else {
            throw EndOfStreamError()
        }
        return msg
    }

    func Close() {
        MarkClosed()
        _ = Glibc.shutdown(fd, Int32(SHUT_RDWR))
        Glibc.close(fd)
    }
}
